+# Shared complete eligibility; every participant-dependent read is inside a true presence branch.
+nesnd_c2_italian_can_send = {
+ trigger_if = { limit = { exists = $TARGET$ }
+  nesnd_italy_country = yes has_variable = nesnd_c2_italy_foundations_done nesnd_c2_italian_request_free = yes
+  NOT = { this = $TARGET$ } NOT = { has_war_with = $TARGET$ }
