+  }
+  trigger_else = { always = no }
+ }
+ trigger_else = { always = no }
+}
+nesnd_c2_italian_alternative_notice_valid = {
+ trigger_if = { limit = { exists = scope:c2_compact_sender exists = scope:c2_compact_partner exists = scope:c2_compact_serial }
+  this = scope:c2_compact_sender
+  scope:c2_compact_partner = { nesnd_c2_italian_reply_valid = yes }
+ }
+ trigger_else = { always = no }
+}
+nesnd_c2_italian_can_confirm_alternative = {
+ trigger_if = { limit = { exists = scope:c2_compact_sender exists = scope:c2_compact_partner exists = scope:c2_compact_serial }
+  trigger_if = { limit = { nesnd_c2_italian_alternative_notice_valid = yes }
+   scope:c2_compact_partner = { nesnd_c2_italian_can_accept = yes }
+  }
+  trigger_else = { always = no }
+ }
+ trigger_else = { always = no }
+}
